package org.aitu.se.acceptance;

import java.util.Map;

/**
 * Public API of the Acceptance subsystem (subsystem A).
 *
 * <p>The interface belongs to the subsystem, not to the facade: the subsystem can be compiled,
 * used and tested on its own. The facade depends on it (not the other way around), which keeps the
 * dependency graph acyclic ({@code facade -> acceptance}).
 */
public interface IOrderQueue {

    /**
     * Persists a new intake request and reserves the required stock.
     *
     * @param orderId correlation id generated by the caller (the facade)
     * @throws OutOfStockException if the inventory cannot satisfy the order
     */
    void acceptNewOrder(String orderId, Map<String, Integer> items);

    /** Cancels the order and returns the previously reserved stock to the inventory. */
    void cancelAndRestock(String orderId);

    /** Cancels the order without returning stock (goods were already consumed downstream). */
    void cancelWithoutRestock(String orderId);

    /** Returns the persisted order, or {@code null} if it is unknown. */
    IntakeRequest getOrder(String orderId);
}
